$('align').onclick=()=>{let f=items.find(f=>f.id===selected);if(!f)return;if(f.type==='mediaWall'){const choices=mediaWallChoices(f,walls,insideShell,roomAt);if(!choices.length)return notify('找不到可容納電視牆的完整牆段。');commitFurniture(f,anchorMediaWall(f,choices[0],walls));return;}let candidates=[],a=f.rot*Math.PI/180,c=Math.cos(a),s=Math.sin(a);for(const w of(f.type==='beam'?exteriorWallRects():wallRects())){const wallAngle=w.rot*Math.PI/180,tx=Math.cos(wallAngle),tz=-Math.sin(wallAngle);for(const sign of[-1,1]){const nx=Math.sin(wallAngle)*sign,nz=Math.cos(wallAngle)*sign,normalExtent=Math.abs(nx*c-nz*s)*f.w/2+Math.abs(nx*s+nz*c)*f.d/2,tangentExtent=Math.abs(tx*c-tz*s)*f.w/2+Math.abs(tx*s+tz*c)*f.d/2;let along=(f.x-w.x)*tx+(f.z-w.z)*tz;along=Math.max(-w.w/2+tangentExtent,Math.min(w.w/2-tangentExtent,along));let n={...f,x:w.x+tx*along+nx*(normalExtent+w.d/2),z:w.z+tz*along+nz*(normalExtent+w.d/2)};if((ceilingTypes.includes(f.type)||sameRoom(f,n))&&!issues(n,items).length)candidates.push({n,dist:Math.hypot(n.x-f.x,n.z-f.z)});}}candidates.sort((a,b)=>a.dist-b.dist);if(candidates[0]){commitFurniture(f,candidates[0].n);notify('已平移到最近可用牆面；保留原本旋轉角度。')}else notify('找不到足夠寬的可用牆面。');};
